function updateListeningProgress(){const fill=$('#listeningProgressFill'),track=fill?.parentElement,percent=$('#listeningProgressPercent'),title=$('#listeningProgressTitle'),countLabel=$('#listeningProgressCount');const count=listenedParagraphs.size,pct=Math.min(100,count*20);if(fill){fill.style.width=pct+'%';fill.style.flexBasis=pct+'%';fill.style.minWidth=pct?'2px':'0';}if(track){track.setAttribute('aria-valuenow',String(pct));track.setAttribute('aria-label',language==='ar'?'تقدم الاستماع':'Listening progress');}if(percent)percent.textContent=pct+'%';if(title)title.textContent=language==='ar'?'تقدم الاستماع':'Listening progress';if(countLabel)countLabel.textContent=language==='ar'?`${count} من 5 فقرات مكتملة · 20% لكل فقرة`:`${count} of 5 paragraphs completed · 20% each`; }
