     ctx.fillStyle='#6a493e';ctx.strokeStyle='#c58d6c';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(o.x,o.y,o.r*1.25,o.r*.78,0,0,Math.PI*2);ctx.fill();ctx.stroke();
     ctx.strokeStyle='#d8a88a';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(o.x,o.y,o.r*.72,o.r*.42,0,0,Math.PI*2);ctx.stroke();
